css:
.card { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; font-size: 19px; text-align: left; max-width: 600px; margin: 0 auto; padding: 24px; line-height: 1.6; }
.grammar-point { font-size: 14px; color: #8ab4f8; font-weight: bold; margin-bottom: 12px; }
.sentence { font-size: 21px; font-weight: 500; margin-bottom: 14px; }
.cloze { font-weight: bold; color: #3b82f6; }
.prompt { font-size: 15px; color: #fbbc04; margin-bottom: 8px; }
.sentence-meaning { font-size: 15px; color: #9aa0a6; margin-bottom: 12px; }
hr { border: 0; height: 1px; background-color: #555; margin: 18px 0; }
.explanation-title { font-size: 15px; font-weight: bold; margin-top: 14px; margin-bottom: 6px; color: #81c995; }
.mistake-title { font-size: 15px; font-weight: bold; margin-top: 14px; margin-bottom: 6px; color: #f28b82; }
.explanation, .mistake { font-size: 15px; line-height: 1.6; }
